extern alias game;
using System.Net.Sockets;
using System.Text.Json;
using RankType=game::BscTable.RANKING_BOARD_TYPE;
internal static class RankingTest {
    private sealed class Peer(string root) : IDisposable
    {
        private readonly TcpClient socket=new();
        private readonly WireCodec codec=new(JsonSerializer.Deserialize<int[]>(File.ReadAllText(Path.Combine(root,"LocalServer/data/packet-keys.json")))!);
        public SessionKeyInfo Key=new();public byte[] Last=[];
        private async Task<(ushort Command,byte[] Payload)> Send(TcpClient client,ushort cmd,object request)
        {
            await client.GetStream().WriteAsync(codec.Encode(cmd,WireCodec.Serialize(request),true));using var timeout=new CancellationTokenSource(10000);
            var r=codec.Decode((await WireCodec.ReadFrame(client.GetStream(),timeout.Token))!,true);return(r.Command,r.Payload);
        }
        public async Task Login(LocalRuntime server,string account="local-player")
        {
            using var login=new TcpClient();await login.ConnectAsync("127.0.0.1",server.LoginPort);
            await Send(login,(ushort)LoginServerCommand.LS_LOGIN_REQUEST,new LsLoginRequest{userID=account,userPW="local",osType=DeviceOSType.DEVICE_PC});
            var start=(LsGameStartOk)WireCodec.Deserialize(typeof(LsGameStartOk),(await Send(login,(ushort)LoginServerCommand.LS_GAME_START_REQUEST,new LsGameStartRequest{serverId=1,bAgreement=true})).Payload)!;
            Key=new(){uid=start.uid,loginSessionKey=start.loginSessionKey};await socket.ConnectAsync("127.0.0.1",server.GamePort);
        }
        public async Task<T> Request<T>(GameServerCommand command,object body,bool success=true,bool retry=false)
        {
            if(!retry)Key.sequenceNo++;body.GetType().GetField("keyInfo")?.SetValue(body,Key);
            var result=await Send(socket,(ushort)command,body);string expected=command.ToString().Replace("_REQUEST",success?"_OK":"_FAIL");
            if(((GameServerCommand)result.Command).ToString()!=expected)throw new Exception("Expected "+expected+", got "+(GameServerCommand)result.Command+": "+((FailPacket)WireCodec.Deserialize(typeof(FailPacket),result.Payload)!).message);
            Last=result.Payload;if(typeof(T)==typeof(object))return(T)new object();
            var decoded=WireCodec.Deserialize(typeof(T),Last)!;
            if(decoded is GsGetRankingBoardTopRankerOk ranks)while(ranks.currentCount<ranks.totalCount){
                using var timeout=new CancellationTokenSource(10000);var part=codec.Decode((await WireCodec.ReadFrame(socket.GetStream(),timeout.Token))!,true);if(part.Command!=result.Command)throw new Exception("Unexpected rank continuation");var next=(GsGetRankingBoardTopRankerOk)WireCodec.Deserialize(typeof(GsGetRankingBoardTopRankerOk),part.Payload)!;ranks.currentCount+=next.currentCount;ranks.topRankerList.AddRange(next.topRankerList);
            }
            if(decoded is GsGetWorldBossTopRankerOk bosses)while(bosses.currentCount<bosses.totalCount){
                using var timeout=new CancellationTokenSource(10000);var part=codec.Decode((await WireCodec.ReadFrame(socket.GetStream(),timeout.Token))!,true);if(part.Command!=result.Command)throw new Exception("Unexpected boss rank continuation");var next=(GsGetWorldBossTopRankerOk)WireCodec.Deserialize(typeof(GsGetWorldBossTopRankerOk),part.Payload)!;bosses.currentCount+=next.currentCount;bosses.topRankerList.AddRange(next.topRankerList);
            }
            return(T)decoded;
        }
        public Task<LocalEquipmentReply> Batch(LocalEquipmentRequest body)=>Request<LocalEquipmentReply>(GameServerCommand.GS_EXTRACT_EQUIPMENT_ITEM_REQUEST,body);
        public void Dispose()=>socket.Dispose();
    }

    private static LocalPlayer Prepare(LocalRuntime r,string account,string nick){var p=r.Store.GetOrCreate(account);p.Nickname=nick;p.Level=99;p.Exp=ProgressionRules.PlayerFloor(r.Catalog,99);p.Gold=100000000;p.CashPoint=1000000;ulong day=(ProtocolRouter.Now+8*3600)/86400;p.AttendanceDays=1;p.AttendanceLastDay=day;p.AttendanceVipClaimedDay=day;p.ShortTermDays=1;p.ShortTermLastDay=day;return p;}
    private static LocalGuild MakeGuild(LocalPlayer p,uint id,string name,ulong score){var g=new LocalGuild{Id=id,Name=name,Master=p.Uid,Emblem=1,Level=1,Created=ProtocolRouter.Now,TotalDonationPoints=score};g.Members[p.Uid]=new(){Grade=GuildUserGrade.GUILD_USER_GRADE_MASTER,Contribution=(uint)score};p.FoundedGuilds.Add(g);p.Guild.GuildId=id;return g;}
    public static async Task Fixture(string root,string output){
        output=Path.GetFullPath(output);if(!output.StartsWith(@"I:\BnsmMobileWork\verification\",StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Isolated fixture required");Directory.CreateDirectory(output);await using var r=new LocalRuntime(root,Path.Combine(output,"saves"),0,0,0,false);
        if(r.Store.All().Count==0){var p=Prepare(r,"local-player","排行测试");p.Ranking.Initialized=true;p.Ranking.EngravingTotal=77;p.Ranking.ChargedTotal=600;p.Ranking.ChargeDay=ProtocolRouter.TowerDay(ProtocolRouter.Now);p.Ranking.ChargedToday=60;p.Ranking.BigBossDamage=5000000000;p.Ranking.WorldBest=10000;p.Ranking.ComboBest=20000;p.Wander.BestPoints=1250;MakeGuild(p,1,"排行门派",1200);
            for(int i=0;i<20;i++){var q=Prepare(r,"ranking-native-"+i,"本地对照"+i);q.Ranking=new(){Initialized=true,HasPower=true,TigerPower=1000000u+(uint)i*100,DragonPower=1000000,SnakePower=1000000,ArenaPower=2000000,InfinitePower=3000000,EngravingTotal=(ulong)(100+i),ChargedTotal=(ulong)(1000+i),ChargeDay=ProtocolRouter.TowerDay(ProtocolRouter.Now),ChargedToday=(ulong)(100+i),WorldBest=(uint)(30000+i),ComboBest=(uint)(40000+i),BigBossDamage=(ulong)(6000000000+i)};q.Wander.BestPoints=(uint)(3000+i);if(i==0)MakeGuild(q,2,"对照门派",2400);}
            r.Store.Save();}
        await using var app=await DebugToolsTest.Host(r);var addresses=app.Services.GetRequiredService<Microsoft.AspNetCore.Hosting.Server.IServer>().Features.Get<Microsoft.AspNetCore.Hosting.Server.Features.IServerAddressesFeature>()!;File.WriteAllText(Path.Combine(output,"endpoints.json"),JsonSerializer.Serialize(new{directoryPort=r.DirectoryPort,debugPort=new Uri(addresses.Addresses.Single()).Port,productionSaveUsed=false}));await Task.Delay(TimeSpan.FromMinutes(30));
    }
    public static async Task Run(string root){
        var checks=new List<string>();void Check(bool value,string label){if(!value)throw new Exception(label);checks.Add(label);}
        string area=Path.Combine(@"I:\BnsmMobileWork\verification","ranking-"+Guid.NewGuid().ToString("N"));
        await using(var r=new LocalRuntime(root,area,0,0,0,false)){
            var p=Prepare(r,"rank-a","甲方");var q=Prepare(r,"rank-b","乙方");var third=Prepare(r,"rank-c","丙方");p.VipExp=1000000;r.Store.Save();using var a=new Peer(root);using var b=new Peer(root);using var c=new Peer(root);await a.Login(r,p.Account);await b.Login(r,q.Account);await c.Login(r,third.Account);
            async Task<GsGetRankingBoardTopRankerOk> Board(RankType type,Peer? peer=null)=>await (peer??a).Request<GsGetRankingBoardTopRankerOk>(GameServerCommand.GS_GET_RAINKING_BOARD_TOP_RANKER_REQUEST,new GsGetRankingBoardTopRankerRequest{rankingBoardType=type});
            async Task Bad(Peer peer,GameServerCommand cmd,object body,string text,bool retry=false){var error=await peer.Request<FailPacket>(cmd,body,false,retry);Check(error.errorCode!=0,text);}
            var rank=await Board(RankType.RANKING_BOARD_BATTLE_ABILITY);Check(rank.totalCount==0&&rank.currentCount==0&&rank.userRankData!=null,"Unreported power is not fabricated and empty list terminates");
            rank=await Board(RankType.RANKING_BOARD_BUY_CASH);Check(rank.totalCount==0&&p.Ranking.ChargedTotal==0,"Debug VIP and free diamonds are not counted as recharge");
            await a.Request<GsGetChangedMissionListOk>(GameServerCommand.GS_GET_CHANGED_MISSION_LIST_REQUEST,new GsGetChangedMissionListRequest{needBattleAbilityRefresh=true,whiteTigerBattleAbility=100,blueDragonBattleAbility=200,redSnakeBattleAbility=300});
            await b.Request<GsGetChangedMissionListOk>(GameServerCommand.GS_GET_CHANGED_MISSION_LIST_REQUEST,new GsGetChangedMissionListRequest{needBattleAbilityRefresh=true,whiteTigerBattleAbility=300,blueDragonBattleAbility=300,redSnakeBattleAbility=300});
            await c.Request<GsGetChangedMissionListOk>(GameServerCommand.GS_GET_CHANGED_MISSION_LIST_REQUEST,new GsGetChangedMissionListRequest{needBattleAbilityRefresh=true,whiteTigerBattleAbility=300,blueDragonBattleAbility=300,redSnakeBattleAbility=300});
            rank=await Board(RankType.RANKING_BOARD_BATTLE_ABILITY);Check(rank.totalCount==3&&rank.userRankData.ranking==3&&rank.userRankData.rankingData==600,"All-card rank and own rank use original reported faction sum");Check(rank.topRankerList[0].rankUserInfo.uid==q.Uid&&rank.topRankerList[1].rankUserInfo.uid==third.Uid,"Ties use deterministic UID order");
            rank=await Board(RankType.RANKING_BOARD_BATTLE_ABILITY_RED_SNAKE);Check(rank.topRankerList[0].rankUserInfo.uid==p.Uid&&rank.userRankData.rankingData==300,"Faction filter uses its own score");
            await a.Request<GsCheckGameEntryOk>(GameServerCommand.GS_CHECK_GAME_ENTRY_REQUEST,new GsCheckGameEntryRequest{ArenaDefenceDeckBattleAbility=1234,InfiniteArenaDefenceDeckBattleAbility=2345});Check(p.Ranking.TigerPower==100&&p.Ranking.SnakePower==300,"Normal polling zeros do not erase faction power");
            rank=await Board(RankType.RANKING_BOARD_ARENA_BATTLE_REAL_TIME);Check(rank.userRankData.rankingData==1234,"Arena live board uses defence-deck power, not fictional wins");
            rank=await Board(RankType.RANKING_BOARD_INFINITE_ARENA_BATTLE_REAL_TIME);Check(rank.userRankData.rankingData==2345,"Infinite defence power board");
            var arena=await a.Request<GsGetRankingBoardArenaBattleDetailInfoOk>(GameServerCommand.GS_GET_RAINKING_BOARD_ARENA_BATTLE_DETAIL_REQUEST,new GsGetRankingBoardArenaBattleDetailInfoRequest{targetUid=p.Uid,rankingBoardType=RankType.RANKING_BOARD_ARENA_BATTLE_REAL_TIME});Check(arena.userData!=null&&arena.guildInfo!=null&&arena.userRankData!=null&&arena.battleCardInfoList.All(x=>x.uid==p.Uid),"Native defence detail has complete non-null profile and owned cards");
            foreach(var type in Enum.GetValues<RankType>()){rank=await Board(type);Check(rank.userRankData!=null&&rank.currentCount==rank.topRankerList.Count&&rank.currentCount==rank.totalCount,"Native count contract for "+type);}
            var profile=await a.Request<GsGetRankingBoardCommonDetailInfoOk>(GameServerCommand.GS_GET_RAINKING_BOARD_COMMON_DETAIL_REQUEST,new GsGetRankingBoardCommonDetailInfoRequest{targetUid=q.Uid});Check(profile.userData.nick==q.Nickname&&profile.guildInfo.guildName=="","Common profile supports players without guilds");
            await Bad(a,GameServerCommand.GS_GET_RAINKING_BOARD_COMMON_DETAIL_REQUEST,new GsGetRankingBoardCommonDetailInfoRequest{targetUid=uint.MaxValue},"Unknown profile rejected");
            await Bad(a,GameServerCommand.GS_GET_RAINKING_BOARD_ARENA_BATTLE_DETAIL_REQUEST,new GsGetRankingBoardArenaBattleDetailInfoRequest{targetUid=p.Uid,rankingBoardType=RankType.RANKING_BOARD_ARENA_BATTLE},"Unrestored competitive win history is not invented");
            var product=r.Catalog.BuyCashProducts.First(x=>x.CNY>0&&x.Value>0&&x.BuyType==BscTable.BUY_CASH_DATA_TYPE.BUY_CASH);await a.Request<GsBuyCashProductOk>(GameServerCommand.GS_BUY_CASH_PRODUCT_REQUEST,new GsBuyCashProductRequest{cashProductId=(uint)product.Id});uint charged=p.PendingCharge!.VipExperience??p.PendingCharge.Cash;
            await a.Request<GsCashProductDeliveryOk>(GameServerCommand.GS_CASH_PRODUCT_DELIVERY_REQUEST,new GsCashProductDeliveryRequest());Check(p.Ranking.ChargedTotal==charged&&p.Ranking.ChargedToday==charged,"Only delivered simulated order increments recharge boards");await a.Request<GsCashProductDeliveryOk>(GameServerCommand.GS_CASH_PRODUCT_DELIVERY_REQUEST,new GsCashProductDeliveryRequest(),retry:true);Check(p.Ranking.ChargedTotal==charged,"Delivery retry does not duplicate recharge rank points");
            p.Ranking.ChargeDay--;rank=await Board(RankType.RANKING_BOARD_BUY_CASH_TODAY);Check(rank.totalCount==0&&p.Ranking.ChargedTotal==charged,"04:00 daily recharge reset preserves lifetime total");
            var gear=r.Catalog.Items.First(x=>x.ItemType==BscTable.ITEM_TYPE.ITEM_TYPE_EQUIPMENT&&x.Step==5&&x.CardId==0&&x.Extraction&&x.Empower);var owned=new LocalOwnedEquipment{ItemId=(uint)gear.Id,Sequence=p.NextEquipmentSequence++,RegisteredAt=ProtocolRouter.Now};p.EquipmentItems.Add(owned);
            var stone=r.Catalog.Items.First(x=>x.ItemType==BscTable.ITEM_TYPE.ITEM_TYPE_EMPOWERSTONE&&x.EmpowerValue>0&&x.EmpowerValue<=gear.EmpowerMaxCost&&x.EmpowerLimitItemLevel<=gear.Level);p.Inventory[(uint)stone.Id]=3;
            var engrave=new GsEmpowerEquipmentItemRequest{equipmentItemSeq=owned.Sequence};engrave.empowerStoneItemIdList.Add((uint)stone.Id);await a.Request<GsEmpowerEquipmentItemOk>(GameServerCommand.GS_EMPOWER_EQUIPMENT_ITEM_REQUEST,engrave);Check(p.Ranking.EngravingTotal==(uint)stone.EmpowerValue,"Original stone value increments cumulative engraving");await a.Request<GsEmpowerEquipmentItemOk>(GameServerCommand.GS_EMPOWER_EQUIPMENT_ITEM_REQUEST,engrave,retry:true);Check(p.Ranking.EngravingTotal==(uint)stone.EmpowerValue,"Engraving replay cannot duplicate leaderboard credit");
            await a.Request<GsResetEmpowerEquipmentItemOk>(GameServerCommand.GS_RESET_EMPOWER_EQUIPMENT_ITEM_REQUEST,new GsResetEmpowerEquipmentItemRequest{equipmentItemSeq=owned.Sequence});Check(owned.CurrentEmpowerValue==0&&p.Ranking.EngravingTotal==(uint)stone.EmpowerValue,"Reset does not erase cumulative engraving history");
            var guild=MakeGuild(p,1,"测试门派",100);rank=await Board(RankType.RANKING_BOARD_GUILD_CONTRIBUTION);Check(rank.totalCount==1&&rank.topRankerList[0].rankGuildInfo.guildID==1&&rank.userRankData.rankingData==100,"Guild board carries native guild objects and own guild rank");
            await a.Request<GsGetGuildContributionInfoOk>(GameServerCommand.GS_GET_GUILD_CONTRIBUTION_INFO_REQUEST,new GsGetGuildContributionInfoRequest());var ticket=r.Catalog.Items.First(x=>x.ItemSubType==BscTable.ITEM_SUB_TYPE.ITEM_SUB_TYPE_TICKET_CONTRIBUTION);p.Inventory[(uint)ticket.Id]=10;var donated=await a.Request<GsGuildContributionOk>(GameServerCommand.GS_GUILD_CONTRIBUTION_REQUEST,new GsGuildContributionRequest{itemInfo=new(){itemID=(uint)ticket.Id,itemCount=1}});Check(guild.TotalDonationPoints>100,"Real guild donation increments lifetime donation score");ulong donation=guild.TotalDonationPoints!.Value;
            guild.Points=1000000;await a.Request<GsGuildLevelUpOk>(GameServerCommand.GS_GUILD_LEVEL_UP_REQUEST,new GsGuildLevelUpRequest());Check(guild.TotalDonationPoints==donation&&guild.Points<1000000,"Spending guild points on levels does not reduce donation ranking");var detail=await a.Request<GsGetRankingBoardGuildDetailInfoOk>(GameServerCommand.GS_GET_RAINKING_BOARD_GUILD_DETAIL_REQUEST,new GsGetRankingBoardGuildDetailInfoRequest{targetGuildId=1});Check(detail.guildContributionRank==1&&detail.guildInfo.guildName==guild.Name,"Guild ranking detail has real contribution place");
            p.Ranking.BigBossDamage=5000000000;p.Wander.BestPoints=1234;p.Ranking.WorldBest=7000;p.Ranking.ComboBest=8000;
            rank=await Board(RankType.RANKING_BOARD_BIG_BOSS_DAMAGE);Check(rank.userRankData.rankingData==5000000000,"Damage ranking retains 64-bit values above signed integer range");
            var wander=await a.Request<GsGetRankingBoardWanderBattleDetailInfoOk>(GameServerCommand.GS_GET_RAINKING_BOARD_WANDER_BATTLE_DETAIL_REQUEST,new GsGetRankingBoardWanderBattleDetailInfoRequest{targetUid=p.Uid});Check(wander.userRankData.rankingData==1234,"Wander detail uses achieved persistent best points");
            var world=await a.Request<GsGetRankingBoardWorldBossDetailInfoOk>(GameServerCommand.GS_GET_RAINKING_BOARD_WORLD_BOSS_DETAIL_REQUEST,new GsGetRankingBoardWorldBossInfoRequest{targetUid=p.Uid,rankingBoardType=RankType.RANKING_BOARD_WORLD_BOSS_COMBO});Check(world.userRankData.rankingData==8000&&world.userRankData.worldBossComboReward==0,"Combo record has no fabricated original-server ranking rewards");
            var likes=await a.Request<GsGetLikeYouInfoOk>(GameServerCommand.GS_GET_LIKE_YOU_INFO_REQUEST,new GsGetLikeYouInfoRequest());uint quota=(uint)r.Catalog.Numbers[BscTable.NUMBER_TYPE.DAILY_LIKE_SEND_COUNT];Check(likes.remainLikeYouPoint==quota,"Original daily like quota");
            await Bad(a,GameServerCommand.GS_SEND_LIKE_YOU_REQUEST,new GsSendLikeYouRequest{targetUid=p.Uid},"Cannot like oneself");await Bad(a,GameServerCommand.GS_SEND_LIKE_YOU_REQUEST,new GsSendLikeYouRequest{targetUid=900001},"Ambient actors are not invented leaderboard contestants");
            var liked=await a.Request<GsSendLikeYouOk>(GameServerCommand.GS_SEND_LIKE_YOU_REQUEST,new GsSendLikeYouRequest{targetUid=q.Uid});Check(liked.remainLikeYouPoint==quota-1&&q.Ranking.ReceivedTotal==1,"Like updates sender and receiver atomically");await a.Request<GsSendLikeYouOk>(GameServerCommand.GS_SEND_LIKE_YOU_REQUEST,new GsSendLikeYouRequest{targetUid=q.Uid},retry:true);Check(q.Ranking.ReceivedTotal==1,"Like retry safe");
            await Bad(a,GameServerCommand.GS_SEND_LIKE_YOU_REQUEST,new GsSendLikeYouRequest{targetUid=third.Uid},"Changed retry rejected",true);await Bad(a,GameServerCommand.GS_SEND_LIKE_YOU_REQUEST,new GsSendLikeYouRequest{targetUid=q.Uid},"Daily duplicate like rejected");
            for(int i=0;i<4;i++){var target=Prepare(r,"like-target-"+i,"点赞目标"+i);await a.Request<GsSendLikeYouOk>(GameServerCommand.GS_SEND_LIKE_YOU_REQUEST,new GsSendLikeYouRequest{targetUid=target.Uid});}await Bad(a,GameServerCommand.GS_SEND_LIKE_YOU_REQUEST,new GsSendLikeYouRequest{targetUid=third.Uid},"Original send quota enforced");
            for(int i=0;i<5;i++){var sender=Prepare(r,"like-sender-"+i,"点赞者"+i);using var peer=new Peer(root);await peer.Login(r,sender.Account);if(i<4)await peer.Request<GsSendLikeYouOk>(GameServerCommand.GS_SEND_LIKE_YOU_REQUEST,new GsSendLikeYouRequest{targetUid=q.Uid});else await Bad(peer,GameServerCommand.GS_SEND_LIKE_YOU_REQUEST,new GsSendLikeYouRequest{targetUid=q.Uid},"Original receiver daily like cap enforced");}
            p.Ranking.LikeDay--;likes=await a.Request<GsGetLikeYouInfoOk>(GameServerCommand.GS_GET_LIKE_YOU_INFO_REQUEST,new GsGetLikeYouInfoRequest());Check(likes.remainLikeYouPoint==quota&&likes.likeyouSendTargetUidList.Count==0,"UTC+8 midnight refreshes likes");
            uint boss=(uint)new RaidCatalog(root).World.First().Id;p.Raids.BestDamage[boss]=1000;q.Raids.BestDamage[boss]=2000;
            var bossRank=await a.Request<GsGetWorldBossTopRankerOk>(GameServerCommand.GS_GET_WORLD_BOSS_TOP_RANKER_REQUEST,new GsGetWorldBossTopRankerRequest{bossId=boss});Check(bossRank.totalCount==2&&bossRank.userRankData.ranking==2&&bossRank.topRankerList[0].rankUserInfo.uid==q.Uid&&bossRank.topRankerList.All(x=>x.cardInfo.Count==20),"Per-boss leaderboard compares real accounts and preserves 20-card contract");
            for(int i=0;i<120;i++){var other=Prepare(r,"rank-bulk-"+i,"榜单角色"+i);other.Ranking=new(){Initialized=true,HasPower=true,TigerPower=(uint)(10000+i),DragonPower=10000,SnakePower=10000};other.Raids.BestDamage[boss]=(uint)(10000+i);}
            rank=await Board(RankType.RANKING_BOARD_BATTLE_ABILITY);Check(rank.totalCount==100&&rank.currentCount==100&&rank.topRankerList.Count==100&&rank.userRankData.ranking==123,"Top 100 spans seven encrypted frames while own rank beyond 100 remains available");
            bossRank=await a.Request<GsGetWorldBossTopRankerOk>(GameServerCommand.GS_GET_WORLD_BOSS_TOP_RANKER_REQUEST,new GsGetWorldBossTopRankerRequest{bossId=boss});Check(bossRank.currentCount==100&&bossRank.userRankData.ranking==122,"Per-boss top 100 spans thirteen bounded frames");
            await a.Request<GsGetChangedMissionListOk>(GameServerCommand.GS_GET_CHANGED_MISSION_LIST_REQUEST,new GsGetChangedMissionListRequest{needBattleAbilityRefresh=true});Check(p.Ranking.HasPower&&p.Ranking.TigerPower==0&&p.Ranking.DragonPower==0&&p.Ranking.SnakePower==0,"Explicit original power refresh may clear power to zero");r.Store.Save();
        }
        await using(var r=new LocalRuntime(root,area,0,0,0,false)){var p=r.Store.GetOrCreate("rank-a");Check(p.Ranking.EngravingTotal>0&&p.Ranking.ChargedTotal>0&&p.Ranking.BigBossDamage==5000000000&&p.Ranking.Liked.Count==0,"All ranking counters and daily state survive restart");using var a=new Peer(root);await a.Login(r,p.Account);var rank=await a.Request<GsGetRankingBoardTopRankerOk>(GameServerCommand.GS_GET_RAINKING_BOARD_TOP_RANKER_REQUEST,new GsGetRankingBoardTopRankerRequest{rankingBoardType=RankType.RANKING_BOARD_BUY_CASH});Check(rank.userRankData.ranking==1&&rank.userRankData.rankingData==p.Ranking.ChargedTotal,"Own rank survives full server restart");}
        File.WriteAllText(Path.Combine(root,"evidence/ranking-protocol-test.json"),JsonSerializer.Serialize(new{passed=true,checks,productionSaveUsed=false},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("Ranking protocol: "+checks.Count+" checks passed");
    }
